CREATE OR REPLACE FUNCTION public.protect_attempt_user_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF OLD.user_id IS NOT NULL AND NEW.user_id IS NOT NULL AND OLD.user_id <> NEW.user_id THEN
        RAISE EXCEPTION 'user_id cannot be changed once associated';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_session_mac()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.client_mac = public.normalize_mac(NEW.client_mac);
  NEW.ap_mac = public.normalize_mac(NEW.ap_mac);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
